import{_ as e,o,c as a,a2 as i}from"./chunks/framework.D9E58p8B.js";const g=JSON.parse('{"title":"Acting","description":"","frontmatter":{"title":"Acting"},"headers":[],"relativePath":"en/agent/agir.md","filePath":"en/agent/agir.md"}'),n={name:"en/agent/agir.md"};function d(r,t,c,s,h,l){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="acting" tabindex="-1">Acting <a class="header-anchor" href="#acting" aria-label="Permalink to &quot;Acting&quot;">​</a></h1><p>Mains (Hands) lets the agent click, type text, press a button, drag and drive windows. This is what <strong>you</strong> bound, with the ceiling.</p><h2 id="what-you-ask" tabindex="-1">What you ask <a class="header-anchor" href="#what-you-ask" aria-label="Permalink to &quot;What you ask&quot;">​</a></h2><blockquote><p>&quot;Open the File menu.&quot;</p><p>&quot;Fill the Name field with &quot;Dupont&quot;, then confirm.&quot;</p></blockquote><h2 id="before-acting-the-ceiling" tabindex="-1">Before acting: the ceiling <a class="header-anchor" href="#before-acting-the-ceiling" aria-label="Permalink to &quot;Before acting: the ceiling&quot;">​</a></h2><p>The ceiling is set to <strong>L0</strong> by default: the agent can only observe. For it to act, raise the panel&#39;s slider (L1 to L3): see <a href="/Daimon/en/guide/plafond-et-exclusions.html">Ceiling and exclusions</a>.</p><p>A well-driven agent first calls <a href="/Daimon/en/reference/diagnostic.html#main-ceiling"><code>main_ceiling</code></a>. The tool returns the active ceiling, and <code>gated_above</code> lists the tools refused at this level: the agent announces up front what it will not be able to do, instead of being refused along the way. <strong>It cannot raise the ceiling</strong>: that is for you to do.</p><table tabindex="0"><thead><tr><th>Level</th><th>What it allows</th><th>Tools</th></tr></thead><tbody><tr><td>L1</td><td>Reversible actions: focus, windows, navigation</td><td><code>main_navigate</code>, <code>main_hover</code>, <code>main_activate</code>, <code>main_window_*</code></td></tr><tr><td>L2</td><td>Clicks, typing, dragging, keys</td><td><code>main_click</code>, <code>main_type</code>, <code>main_drag</code>, <code>main_key</code></td></tr><tr><td>L3</td><td>Buttons that commit</td><td><code>main_press</code></td></tr><tr><td>L4</td><td>Everything, without per-action confirmation</td><td><code>main_mouse_*</code>, <code>main_key_down</code>, <code>main_key_up</code></td></tr></tbody></table><h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><ol><li>It <strong>looks</strong>: <a href="/Daimon/en/agent/regarder.html">Looking at the screen</a> or <a href="/Daimon/en/agent/lire-interface.html">Reading an interface</a>, to obtain a reliable position.</li><li>It <strong>acts</strong>, declaring its <code>intent</code>: a sentence saying what it wants to do, recorded in the audit log. Tools that commit also carry <code>reversible</code>, which the agent must fill in honestly.</li><li>It <strong>verifies</strong>: a new look confirms the result.</li></ol><p>To click, the agent preferably passes <code>role</code> and <code>label</code> (read with <code>touche_probe</code>): Daimon can then check the target&#39;s reversibility. To type, it first clicks in the field, because <code>main_type</code> does not choose the target. The typed text is <strong>never</strong> written to the audit log.</p><p>To aim, the agent gives either global points (those returned by <code>vue_find</code>), or, with <code>space=&quot;image&quot;</code> and a <code>display</code>, pixels of a capture that Daimon converts itself.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><p>Each action tool answers in one of these three forms:</p><table tabindex="0"><thead><tr><th>Response</th><th>Meaning</th></tr></thead><tbody><tr><td><code>{&quot;status&quot;: &quot;done&quot;, …}</code></td><td>The action was executed</td></tr><tr><td><code>{&quot;status&quot;: &quot;refused&quot;, &quot;reason&quot;: &quot;…&quot;}</code></td><td>The action is refused: ceiling, guard, human confirmation not obtained</td></tr><tr><td><code>{&quot;status&quot;: &quot;error&quot;, &quot;reason&quot;: &quot;…&quot;}</code></td><td>The action could not run</td></tr></tbody></table><h2 id="confirmations" tabindex="-1">Confirmations <a class="header-anchor" href="#confirmations" aria-label="Permalink to &quot;Confirmations&quot;">​</a></h2><p>Up to L3, an action that Daimon judges <strong>irreversible</strong>, or that the agent declares as such, stops on a confirmation dialog. You answer; without an answer, it declines by itself after 30 seconds, and the agent receives <code>refused</code>.</p><p>At <strong>L4</strong>, there is no more per-action confirmation. This level requires your explicit consent, from the panel or the terminal; no tool lets the agent engage it.</p><h2 id="if-the-call-is-refused-or-fails" tabindex="-1">If the call is refused or fails <a class="header-anchor" href="#if-the-call-is-refused-or-fails" aria-label="Permalink to &quot;If the call is refused or fails&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Case</th><th>What the agent should do</th></tr></thead><tbody><tr><td><code>refused</code> above the ceiling</td><td>Say that the action exceeds the ceiling, and ask the person to raise it if they wish</td></tr><tr><td><code>refused</code>, confirmation not obtained</td><td>Do not insist: the person declined or did not answer</td></tr><tr><td><code>done</code> with no effect at all</td><td>Without the <strong>Accessibilité</strong> (Accessibility) permission, <code>main_type</code>, <code>main_key</code>, <code>main_hover</code> and <code>main_navigate</code> answer <code>done</code> <strong>without doing anything</strong>: call <code>daimon_doctor</code></td></tr><tr><td>30-second wait</td><td>Without Accessibility, <code>main_click</code>, <code>main_press</code> and <code>main_drag</code> wait for a confirmation: call <code>daimon_doctor</code></td></tr><tr><td><code>invalid_arguments</code></td><td>For example <code>space=&quot;image&quot;</code> without <code>display</code>: fix the argument</td></tr><tr><td><code>motor_unavailable</code></td><td>Mains is not available on this host</td></tr></tbody></table><p>Full detail: <a href="/Daimon/en/reference/mains.html">Mains</a>.</p><p>Next: <a href="/Daimon/en/agent/montrer.html">Showing what is happening</a>.</p>',22)])])}const m=e(n,[["render",d]]);export{g as __pageData,m as default};
